CREATE TABLE IF NOT EXISTS requests (id BIGSERIAL PRIMARY KEY, customer_name TEXT, confirmation_status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS request_details (request_id BIGINT PRIMARY KEY REFERENCES requests(id) ON DELETE CASCADE, app_number TEXT NOT NULL UNIQUE, registered_date DATE, received_date DATE, staff TEXT, customer_kana TEXT, phone TEXT, work_types_json JSONB NOT NULL DEFAULT '[]', other_work TEXT, position TEXT, thread_font TEXT, embroidery_content TEXT, hemming_method TEXT, length_cm TEXT, hemming_thread TEXT, remaining_fabric TEXT, hemming_notes TEXT, amount TEXT, accounts_receivable TEXT, deposit TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS request_products (id BIGSERIAL PRIMARY KEY, request_id BIGINT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, product_number TEXT, branch_number TEXT, combined_number TEXT, product_name TEXT, color TEXT, size TEXT, quantity TEXT, work_states_json JSONB NOT NULL DEFAULT '[]', notes TEXT);
CREATE TABLE IF NOT EXISTS request_photos (id BIGSERIAL PRIMARY KEY, request_id BIGINT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, photo_type TEXT NOT NULL, file_path TEXT NOT NULL, original_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
